INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(20601, 'Ezekiel 48:14', 'Ezekiel', 48, 14, '&nbsp;هغوئ به نۀ دا خرڅوى او نۀ به يې بدلوى. دا ښۀ زمکه ده او نۀ دى په کار چې نورو لاسونو ته لاړه شى، ځکه چې دا مالِک خُدائ ته مقدسه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20602, 'Ezekiel 48:15', 'Ezekiel', 48, 15, '&nbsp;پاتې دولس نيم کيلوميټره پلنه او دوه نيم کيلوميټره اوږده زمکه به د ښار د عام استعمال دپاره، د کورونو او د څرن ځائ دپاره وى. ښار به د دې په مينځ کښې وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20603, 'Ezekiel 48:16', 'Ezekiel', 48, 16, '&nbsp;او د دې ناپونه به دا وى، شمال طرف به پاو باندې دوه کيلوميټره وى، جنوب طرف به پاو باندې دوه کيلوميټره وى، مشرق طرف به پاو باندې دوه کيلوميټره وى، او د مغرب طرف به هم پاو باندې دوه کيلوميټره وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20604, 'Ezekiel 48:17', 'Ezekiel', 48, 17, '&nbsp;د ښار دپاره د څرن ځائ به شمال ته يو نيم سل ګزه مربع وى، جنوب ته به يو نيم سل ګزه مربع وى، مشرق ته به يو نيم سل ګزه مربع وى، او مغرب ته به هم يو نيم سل ګزه مربع وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20605, 'Ezekiel 48:18', 'Ezekiel', 48, 18, '&nbsp;کومه پاتې علاقه چې د مقدسې حصې سره لګېدلې ده او دې سره په اوږدو تلې ده، دا به د مشرق طرف ته پينځۀ کيلوميټره او د مغرب طرف ته به هم پينځۀ کيلوميټره وى. د ښار کارکوونکو دپاره به د دې پېداوار خوراک ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20606, 'Ezekiel 48:19', 'Ezekiel', 48, 19, '&nbsp;د ښار کار کوونکى څوک چې دا کَرى هغوئ به د بنى اِسرائيلو د ټولو قبيلو نه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20607, 'Ezekiel 48:20', 'Ezekiel', 48, 20, '&nbsp;دا ټوله حِصه به هر طرف ته دولس نيم کيلوميټره مربع وى. د خاص تحفې په طور به تاسو مقدسه حِصه، سره د ښار د جائيداد يو طرف ته کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20608, 'Ezekiel 48:21', 'Ezekiel', 48, 21, '&nbsp;څۀ چې پاتې وُو د هغه علاقې په دواړو طرفونو کښې د مقدسې برخې سره او د ښار جائيداد دا به د شهزاده ملکيت وى. دا به د مشرق طرف ته دولس نيم کيلوميټره د مقدسې حصې نه تر مشرقى سرحد وى، او د مغرب طرف نه به دولس نيم کيلوميټره تر مغربى سرحده وى. دا دواړه علاقې چې د قبائيلى حِصو اوږدوالى پورې غزېدلې دى دا به د شهزاده ملکيت وى، او مقدسه حِصه به سره د خُدائ د کور د مقدس ځائ د دې په مينځ کښې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20609, 'Ezekiel 48:22', 'Ezekiel', 48, 22, '&nbsp;نو د ليويانو جائيداد او د ښار جائيداد به د دې علاقې په مينځ کښې پروت وى چې د شهزاده ملکيت دے. کومه علاقه چې د شهزاده ملکيت دے هغه به د يهوداه او د بنيامين د سرحد په مينځ کښې پرته وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20610, 'Ezekiel 48:23', 'Ezekiel', 48, 23, '&nbsp;”نو دغه شان به د نورو قبيلو وى، د بنيامين به يوه حِصه وى، دا به د مشرق طرف نه تر مغرب طرف پورې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20611, 'Ezekiel 48:24', 'Ezekiel', 48, 24, '&nbsp;د شمعون به يوه حِصه وى، دا به د مشرق نه تر مغرب پورې د بنيامين د علاقې سرحد وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20612, 'Ezekiel 48:25', 'Ezekiel', 48, 25, '&nbsp;د يساکار به يوه حِصه وى، دا به د مشرق نه تر مغرب پورې د شمعون د علاقې سرحد وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20613, 'Ezekiel 48:26', 'Ezekiel', 48, 26, '&nbsp;د زبولون به يوه حِصه وى، دا به د مشرق نه تر مغرب پورې د يساکار د علاقې سرحد وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20614, 'Ezekiel 48:27', 'Ezekiel', 48, 27, '&nbsp;د جاد به يوه حِصه وى، دا به د مشرق نه تر مغرب پورې د زبولون د علاقې سرحد وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20615, 'Ezekiel 48:28', 'Ezekiel', 48, 28, '&nbsp;د جاد د زمکې جنوبى پوله به د تامار د جنوب نه د مريبه قادِس د اوبو پورې وى، بيا به د مِصر د وادۍ سره لوئ سمندر پورې تلې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20616, 'Ezekiel 48:29', 'Ezekiel', 48, 29, '&nbsp;دا هغه زمکه ده چې تاسو به يې د ميراث په طور د بنى اِسرائيلو د قبيلو په مينځ کښې تقسيم کړئ، او دا به د هغوئ حِصه وى، مالِک قادر مطلق خُدائ فرمائى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20617, 'Ezekiel 48:30', 'Ezekiel', 48, 30, '&nbsp;”دا به د ښار نه د وتو دروازې وى. د شمال طرف دېوال کوم چې پاو باندې دوه کيلوميټر اوږد دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20618, 'Ezekiel 48:31', 'Ezekiel', 48, 31, '&nbsp;په دې کښې به درې دروازې چې د بنى اِسرائيلو د قبيلو په نومونو ياديږى. د روبين دروازه، د يهوداه د دروازه، او د ليويانو دروازه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20619, 'Ezekiel 48:32', 'Ezekiel', 48, 32, '&nbsp;مشرق طرف ته چې کوم پاو باندې دوه کيلوميټره اوږد دېوال دے په هغې کښې به درې دروازې وى، د يوسف دروازه، د بنيامين دروازه او د دان دروازه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20620, 'Ezekiel 48:33', 'Ezekiel', 48, 33, '&nbsp;د جنوب طرف ته، چې کوم پاو باندې دوه کيلوميټره دېوال دے، په کښې به درې دروازې وى چې به د شمعون دروازه، د يساکار دروازه او د زبولون دروازه ياديږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20621, 'Ezekiel 48:34', 'Ezekiel', 48, 34, '&nbsp;مغرب طرف ته چې کوم پاو باندې دوه کيلوميټره اوږد دېوال دے په کښې به درې دروازې وى، د جاد دروازه، د آشر دروازه او د نفتالى دروازه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20622, 'Ezekiel 48:35', 'Ezekiel', 48, 35, '&nbsp;ټوله فاصله ګېرچاپېره به نهۀ کيلوميټره وى. او د هغې ورځې نه وروستو به د دې ښار نوم دا وى، مالِک خُدائ هلته موجود دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20623, 'Daniel 1:1', 'Daniel', 1, 1, '&nbsp;د يهوداه د بادشاه د يهويقيم د حکومت په درېم کال، د بابل بادشاه نبوکدنضر يروشلم ته راغلو او هغه يې محاصره کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20624, 'Daniel 1:2', 'Daniel', 1, 2, '&nbsp;او مالِک خُدائ يهويقيم د يهوداه بادشاه سره د خُدائ د کور څۀ خاص څيزونه د هغۀ لاسونو ته حواله کړل. هغۀ دا د خُدائ د کور سامانونه بابل ته د خپل معبود کور ته يوړل او دا يې د خپل معبود د کور په خزانه کښې کېښودل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20625, 'Daniel 1:3', 'Daniel', 1, 3, '&nbsp;نو بيا بادشاه د خپل دربار مشر خصى آفسر آشپيناز ته حکم وکړو، چې يو څو بنى اِسرائيليان چې د شاهى خاندان او مخوريزو سړو سره تعلق ساتى راولئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20626, 'Daniel 1:4', 'Daniel', 1, 4, '&nbsp;يو څو ځوانان چې هيڅ قسمه جسمانى عېب په کښې نۀ وى، چې ښکلى، او د هر قسمه زده کړې قابليت په کښې وى، ښۀ هوښيار وى، په پوهېدلو کښې تېز، او د شاهى محل د خِدمت قابل وى راوله. هغه به دې ځوانانو ته د بابل د ژبې او د ادب لوستلو تربيت ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20627, 'Daniel 1:5', 'Daniel', 1, 5, '&nbsp;نو بادشاه د خپل دربار د شاهى دسترخوان نه هغوئ ته د خوراک خوړلو او د ميو څښلو حکم ورکړو. دوئ ته به درې کاله تربيت ورکړے شى او د دې نه وروستو به دوئ د بادشاه د خِدمت دپاره حاضر شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20628, 'Daniel 1:6', 'Daniel', 1, 6, '&nbsp;په هغوئ کښې ځينې د يهوداه د قبيلې وُو لکه دانيال، حننياه، ميشائيل او عزرياه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20629, 'Daniel 1:7', 'Daniel', 1, 7, '&nbsp;هغه د خصيانو مشر آفسر په هغوئ نوى نومونه کېښودل، په دانيال يې بيلطشضر، په حننياه يې شدرک، په ميشائيل يې ميشک، او په عزرياه يې عبدنجو نوم کېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20630, 'Daniel 1:8', 'Daniel', 1, 8, '&nbsp;خو دانيال دا فېصله وکړه چې خپل ځان به په شاهى خوراک او شاهى ميو نۀ پليتوى، او هغۀ د خصيانو د مشر آفسر نه اجازت وغوښتو چې هغه په دې طريقې ځان نۀ پليتوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20631, 'Daniel 1:9', 'Daniel', 1, 9, '&nbsp;نو اوس خُدائ پاک د خصيانو د مشر آفسر په زړۀ کښې د دانيال دپاره مينه او رحم واچولو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20632, 'Daniel 1:10', 'Daniel', 1, 10, '&nbsp;خو د خصيانو مشر آفسر دانيال ته ووئيل، ”زۀ د خپل مالِک بادشاه نه يرېږم، چا چې ستاسو خوراک څښاک مقرر کړے دے. او کۀ هغه تاسو د نورو همزولو ځوانانو نه کمزورى وګورى نو بيا به څۀ کيږى؟ نو بادشاه به بيا ستاسو په وجه زما سر پرې کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20633, 'Daniel 1:11', 'Daniel', 1, 11, '&nbsp;دانيال بيا هغه ملازم ته وفرمائيل کوم چې د خصيانو مشر آفسر په دانيال، حننياه، ميشائيل او عزرياه مقرر کړے وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20634, 'Daniel 1:12', 'Daniel', 1, 12, '&nbsp;”مهربانى وکړئ تاسو د خپلو نوکرانو د لسو ورځو دپاره اندازه واخلئ، او مونږ ته د خوراک دپاره سبزۍ او د څښلو دپاره د اوبو نه بغېر بل څۀ مۀ راکوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20635, 'Daniel 1:13', 'Daniel', 1, 13, '&nbsp;نو بيا زمونږ شکلونه د هغه ځوانانو سره وګوره څوک چې شاهى خوراک څښاک کوى، او بيا د خپلو نوکرانو سره هغه شان وکړه څۀ چې تۀ ګورې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20636, 'Daniel 1:14', 'Daniel', 1, 14, '&nbsp;نو هغه بيا دې خبرې ته راضى شو او لس ورځې يې د هغوئ اندازه واخستله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20637, 'Daniel 1:15', 'Daniel', 1, 15, '&nbsp;د لسو ورځو په آخر کښې هغوئ د نورو ټولو ځوانانو نه صحتمند او ښۀ ښکارېدل چا چې شاهى خوراک کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20638, 'Daniel 1:16', 'Daniel', 1, 16, '&nbsp;نو بيا هغه ملازم د هغوئ نه مقرر شوے خوراک او مے اخوا کړل او د هغې په ځائ يې سبزى ورکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20639, 'Daniel 1:17', 'Daniel', 1, 17, '&nbsp;نو دې څلورو واړو ځوانانو ته خُدائ پاک د هر قسم ادب، عِلم، پوهه او زده کړه ورکړه، او دانيال هم د هر قسم رويا او خوبونو تعبير کولے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20640, 'Daniel 1:18', 'Daniel', 1, 18, '&nbsp;کوم وخت چې بادشاه د هغوئ د تربيت دپاره مقرر کړے وو پوره شو، نو بيا د خصيانو مشر آفسر هغه ټول ځوانان نبوکدنضر ته پېش کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20641, 'Daniel 1:19', 'Daniel', 1, 19, '&nbsp;بادشاه د هغوئ سره خبرې وکړې، او هغۀ يو کس هم په دوئ کښې د دانيال، حننياه، ميشائيل او عزرياه برابر پېدا نۀ کړو، نو هغوئ د بادشاه په دربار کښې په خِدمت کولو مقرر شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20642, 'Daniel 1:20', 'Daniel', 1, 20, '&nbsp;بادشاه د عقل او پوهې په هره مسئله کښې به چې کله د هغوئ نه تپوس کولو، نو هغۀ هغوئ د خپل سلطنت د ټولو جادوګرو او نجوميانو نه لس چنده هوښيار بياموندل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20643, 'Daniel 1:21', 'Daniel', 1, 21, '&nbsp;او دانيال د فارس د خورس د بادشاهۍ اول کال پورې هلته په شاهى دربار کښې خِدمت کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20644, 'Daniel 2:1', 'Daniel', 2, 1, '&nbsp;د خپلې بادشاهۍ په دوېم کال، نبوکدنضر داسې خوبونه وليدل چې د هغۀ سوچ يې ګډ‌وډ کړو، او هغۀ ته بيا خوب نۀ ورتلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20645, 'Daniel 2:2', 'Daniel', 2, 2, '&nbsp;نو بيا بادشاه جادوګر، فالګر، کوډګر او نجوميان راوغوښتل چې هغۀ ته ووائى چې هغۀ څۀ خوب ليدلے دے. هر کله چې هغوئ راغلل او د بادشاه په وړاندې ودرېدل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20646, 'Daniel 2:3', 'Daniel', 2, 3, '&nbsp;هغۀ دوئ ته ووئيل، ”ما يو خوب ليدلے دے کوم چې زۀ ډېر پرېشانه کړے يم او زۀ غواړم چې په دې پوهه شم چې د دې خوب څۀ مطلب دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20647, 'Daniel 2:4', 'Daniel', 2, 4, '&nbsp;نو بيا نجوميانو هغۀ ته په آرامى ژبه کښې ووئيل چې، ”بادشاه سلامت دې تر ابده ژوندے وى. خپلو خادِمانو ته دې خپل خوب بيان کړه، نو مونږ به د هغې تعبير تاسو ته ووايو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20648, 'Daniel 2:5', 'Daniel', 2, 5, '&nbsp;خو بادشاه نجوميانو ته ووئيل، ”ما دا پخه فېصله کړې ده، کۀ چرې تاسو ما ته دا ونۀ وايئ چې زما خوب څنګه وو او تعبير يې نۀ کړئ، نو زۀ به تاسو ټوټه ټوټه کړم او ستاسو کورونه به د خاورو په ډېرو بدل کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20649, 'Daniel 2:6', 'Daniel', 2, 6, '&nbsp;خو کۀ تاسو ما ته زما خوب ووايئ او بيا د هغې تعبير راته ووايئ، نو زۀ به تاسو ته تحفې، انعامونه او لوئ عزت درکړم. اوس تاسو ما ته زما خوب ووايئ او هغه راته تعبير کړئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20650, 'Daniel 2:7', 'Daniel', 2, 7, '&nbsp;نو يو ځل بيا هغوئ هغۀ ته ووئيل، ”بادشاه دې خپلو خادِمانو ته خپل خوب بيان کړى، او مونږ به يې تعبير کړُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20651, 'Daniel 2:8', 'Daniel', 2, 8, '&nbsp;نو بيا بادشاه هغوئ ته په جواب کښې ووئيل، ”زۀ په دې يقين لرم چې تاسو د وخت نه فائده اخلئ، ځکه چې تاسو په دې پوهه شئ چې دا زما پخه فېصله ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20652, 'Daniel 2:9', 'Daniel', 2, 9, '&nbsp;کۀ چرې تاسو ما ته زما خوب ونۀ وايئ، نو بيا تاسو دپاره صرف يوه سزا ده. تاسو دا صلاح کړې ده چې ما ګمراه کړئ او راته دروغ ووايئ او ما دوکه کړئ، او تاسو دا اُميد ساتئ چې زما سوچ به بدل شى. نو بيا تاسو ما ته زما خوب ووايئ، او بيا زۀ به په دې پوهه شم چې تاسو يې ما ته تعبير هم راکولے شئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20653, 'Daniel 2:10', 'Daniel', 2, 10, '&nbsp;نجوميانو بادشاه ته په جواب کښې ووئيل، ”په زمکه داسې هيڅ څوک نشته چې د بادشاه په دې خبره عمل وکړى. تر اوسه پورې داسې نۀ دى شوى چې يو بادشاه د خپل فالګر، جادوګر يا نجومى نه داسې تپوس کړے وى، کۀ هغه بادشاه هر څومره لوئ او طاقتور وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20654, 'Daniel 2:11', 'Daniel', 2, 11, '&nbsp;بادشاه سلامت تاسو چې څۀ غواړئ هغه يو ناممکن کار دے. دا بادشاه ته د هغۀ د معبودانو نه بغېر هيڅ څوک نۀ شى څرګندولے، او هغوئ د انسانانو سره نۀ اوسيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20655, 'Daniel 2:12', 'Daniel', 2, 12, '&nbsp;بادشاه چې کله دا واورېدل نو په دې هغه ډېر زيات په قهر شو او حکم يې وکړو چې د بابل ټول هوښياران او پوهان دې قتل کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20656, 'Daniel 2:13', 'Daniel', 2, 13, '&nbsp;نو بيا د هوښيارانو د قتلولو حکم جارى شو، او د دانيال او د هغۀ ملګرو پسې يې هم کسان ورولېږل چې هغوئ قتل کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20657, 'Daniel 2:14', 'Daniel', 2, 14, '&nbsp;هرکله چې اريوک د بادشاه د محافظانو مشر، د بابل د هوښيارانو قتلولو پسې ووتو نو دانيال په ډېر هوښيارتيا او تميز د هغۀ سره خبرې وکړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20658, 'Daniel 2:15', 'Daniel', 2, 15, '&nbsp;هغۀ د بادشاه د آفسر نه تپوس وکړو چې، ”بادشاه دومره سخت فرمان ولې جارى کړے دے؟“ بيا د بادشاه آفسر اريوک دانيال ته ټوله قيصه بيان کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20659, 'Daniel 2:16', 'Daniel', 2, 16, '&nbsp;نو په دې اورېدو سره دانيال سمدستى بادشاه له ورغلو او د هغۀ نه يې وخت وغوښتلو، چې دے به ورته د خوب تعبير ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20660, 'Daniel 2:17', 'Daniel', 2, 17, '&nbsp;نو بيا دانيال خپل کور ته واپس لاړو او ټوله قيصه يې خپلو ملګرو حننياه، ميشائيل، او عزرياه ته بيان کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20661, 'Daniel 2:18', 'Daniel', 2, 18, '&nbsp;هغۀ دوئ ته خواست وکړو چې آسمانى خُدائ پاک ته د دې راز د څرګندولو په حقله د رحم سوال وکړئ، نو چې دے، د دۀ دوستان او د بابل نور هوښياران قتل نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20662, 'Daniel 2:19', 'Daniel', 2, 19, '&nbsp;په هم هغه شپه دا راز په رويا کښې دانيال ته څرګند شو. نو بيا دانيال د آسمانى خُدائ پاک ثناء صِفت بيان کړو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20663, 'Daniel 2:20', 'Daniel', 2, 20, '&nbsp;او هغۀ وفرمائيل چې، ”د خُدائ پاک نوم ته دې د تل دپاره ثناء صِفت وى، حکمت او قدرت د هغۀ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20664, 'Daniel 2:21', 'Daniel', 2, 21, '&nbsp;هغه وختونه او حالات بدلوى، هغه بادشاهان په تخت کښېنوى او هغوئ اخوا کوى. هغه پوهانو له پوهه او عالمانو له عِلم ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20665, 'Daniel 2:22', 'Daniel', 2, 22, '&nbsp;هغه ژور او پټ د راز څيزونه څرګندوى، هغه ترې خبر دے څۀ چې په تيارۀ کښې پراتۀ دى، او د هغۀ نه ګېرچاپېره نُور دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20666, 'Daniel 2:23', 'Daniel', 2, 23, '&nbsp;زۀ ستا ثناء صِفت او شُکر ګزارى کوم، اے زما د پلار نيکۀ پاکه خُدايه. ځکه چې تا ما له پوهه او قدرت راکړے دے. تا ما ته هغه څۀ وښودل د څۀ چې مونږ ستا نه غوښتنه وکړه، تا ما ته د بادشاه خوب او د هغۀ مسئله څرګنده کړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20667, 'Daniel 2:24', 'Daniel', 2, 24, '&nbsp;نو بيا دانيال اريوک له لاړو، څوک چې بادشاه د بابل د هوښيارانو د قتلولو دپاره مقرر کړے وو، ”د بابل هوښيار خلق مۀ قتلوه. ما بادشاه له بوځه، او زۀ به د هغۀ خوب تعبير هغۀ ته ورکړم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20668, 'Daniel 2:25', 'Daniel', 2, 25, '&nbsp;نو اريوک سمدستى دانيال بادشاه له بوتلو او هغۀ بادشاه ته ووئيل، ”ما د يهوداه په جلاوطنو خلقو کښې يو کس پېدا کړو څوک به چې بادشاه ته د هغۀ د خوب مطلب ووائى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20669, 'Daniel 2:26', 'Daniel', 2, 26, '&nbsp;بادشاه دانيال نه تپوس وکړو، چا ته به يې چې بيلطشضر وئيل، ”آيا تۀ ما ته دا وئيلے شې چې ما څنګه خوب ليدلے دے او د هغې تعبير کولے شې؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20670, 'Daniel 2:27', 'Daniel', 2, 27, '&nbsp;دانيال جواب ورکړو، ”د کوم راز چې بادشاه تپوس کوى هغه هيڅ يو هوښيار، فالګر، جادوګر، او نجومى نۀ شى کولے چې هغه راز بيان کړى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20671, 'Daniel 2:28', 'Daniel', 2, 28, '&nbsp;خو په آسمان کښې يو خُدائ پاک موجود دے څوک چې پټ رازونه څرګندوى، هغۀ چې نبوکدنضر بادشاه ته په خوب کښې ښودلى دى چې په راتلونکو ورځو کښې به څۀ پېښ شى. کله چې تۀ په خپل کټ کښې پروت وې او کوم خوب او رويا چې تا وليدله او ستا په ذهن کښې هغه تيره شوې ده هغه څۀ داسې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20672, 'Daniel 2:29', 'Daniel', 2, 29, '&nbsp;اے بادشاه سلامت کله چې تۀ هلته پروت وې، نو ستا فکر او سوچ د راتلونکو حالاتو طرف ته واوړېدو، او د رازونو ښکاره کوونکى درته دا وښودل چې په آئنده کښې به څۀ کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20673, 'Daniel 2:30', 'Daniel', 2, 30, '&nbsp;دا کوم راز چې ما ته څرګند شو، د دې دا مطلب نۀ دے چې ګنې زۀ دې د نورو کسانو نه ډېر هوښيار يم، خو دا د دې دپاره چې تۀ، اے بادشاه سلامت، د دې راز په تعبير باندې کوم چې ستا په خيال کښې تير شو پوهه شې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20674, 'Daniel 2:31', 'Daniel', 2, 31, '&nbsp;اے بادشاه سلامت تا په خوب کښې وليدل چې يوه لويه ځلېدونکې او حېرانوونکې مجسمه ستا په وړاندې ولاړه وه او هغه يروونکې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20675, 'Daniel 2:32', 'Daniel', 2, 32, '&nbsp;د دې مجسمې سر د خالصو سرو زرو نه جوړ شوے وو، د هغۀ سينه او لاسونه د سپينو زرو نه، د هغۀ ګېډه او پتونونه د زېړو نه جوړ وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20676, 'Daniel 2:33', 'Daniel', 2, 33, '&nbsp;د دې پنډۍ د اوسپنې، او د پښو څۀ حِصه د اوسپنې او څۀ حِصه د پخې شوې خاورې نه جوړه شوې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20677, 'Daniel 2:34', 'Daniel', 2, 34, '&nbsp;هرکله چې تا دې ته کتل، نو په دې وخت کښې د غرۀ نه يو لوئ کاڼے په خپله راجدا شو، خو د انسان په لاسونو نه. هغه د هغه مجسمې په پښو راپرېوتو کومې چې د اوسپنې او خاورو نه جوړې شوې وې او هغه يې ټوټه ټوټه کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20678, 'Daniel 2:35', 'Daniel', 2, 35, '&nbsp;نو بيا اوسپنه، خاوره، زېړ، سپين زر او سرۀ زر ټول ټوټه ټوټه شو او داسې والوتل لکه څنګه چې په اوړى کښې بوس د غنمو په درمند کښې الوځى. هوا هغه ټول يوړل او هيڅ نښه يې پاتې نۀ شوه. خو هغه کاڼى کوم چې دا مجسمه وويشته هغې نه يو لوئ غر جوړ شو او ټوله زمکه يې ونيوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20679, 'Daniel 2:36', 'Daniel', 2, 36, '&nbsp;دا ستا خوب وو، او زۀ به يې اوس تعبير هم درته بيان کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20680, 'Daniel 2:37', 'Daniel', 2, 37, '&nbsp;تاسو، اے بادشاه سلامت، د ټولو بادشاهانو نه لوئ بادشاه يئ. آسمانى خُدائ پاک درته بادشاهى او قدرت، زور شان او شوکت درکړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20681, 'Daniel 2:38', 'Daniel', 2, 38, '&nbsp;هغۀ ستا لاسونو ته ټول انسانان او ځناور او د هوا مارغان حواله کړى دى. چرته چې هم دوئ اوسيږى، هغۀ تۀ په هغوئ ټولو حکمران مقرر کړے يې. او هغه د سرو زرو سر تۀ په خپله يې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20682, 'Daniel 2:39', 'Daniel', 2, 39, '&nbsp;ستا نه وروستو، به يوه بله بادشاهى قائمه شى چې ستا د بادشاهۍ نه به کمزورې وى، او بيا به درېمه بادشاهى راشى، د زېړو به وى، او دا به په ټوله زمکه حکمرانى وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20683, 'Daniel 2:40', 'Daniel', 2, 40, '&nbsp;په آخر کښې به بيا څلورمه بادشاهى راشى چې د اوسپنې په شان به مضبوطه وى ځکه چې اوسپنه هر څۀ ماتوى او ټوټه ټوټه کوى، نو بيا څنګه چې اوسپنه څيزونه ټوټه ټوټه کوى نو داسې به هغه نور ټول مات او ټوټه ټوټه کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20684, 'Daniel 2:41', 'Daniel', 2, 41, '&nbsp;لکه څنګه چې تا وليدل چې د هغې د پښو او ګوتو څۀ حِصه د اوسپنې او څۀ حِصه د پخې خاورې نه جوړه وه نو دا به جدا شوے بادشاهت وى، خو بيا به هم په کښې څۀ نا څۀ د اوسپنې زور پاتې وى، څنګه چې تا اوسپنه خاورې سره يوځائ وليدله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20685, 'Daniel 2:42', 'Daniel', 2, 42, '&nbsp;کۀ څۀ هم چې تا وليدل چې اوسپنه د خټې سره ګډه شوې وه، نو بيا به د دې بادشاهۍ څۀ حِصه طاقتوره او څۀ حِصه کمزورى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20686, 'Daniel 2:43', 'Daniel', 2, 43, '&nbsp;تاسو وليدل چې اوسپنه د خاورې سره يوځائ شوې وه، نو بيا به دغه شان د هغه بادشاهۍ خلق هم کوشش وکړى چې د يو بل سره په وادۀ کولو د يو بل ملاتړ جوړ شى، خو دوئ به په خپلو کښې په اتفاق نۀ شى لکه څنګه چې اوسپنه د خاورو سره يوځائ کېدلے نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20687, 'Daniel 2:44', 'Daniel', 2, 44, '&nbsp;د هغه بادشاهانو په زمانه کښې، به آسمانى خُدائ پاک داسې بادشاهى راولى چې هغه به هيڅکله نۀ ختميږى، نۀ به دا بل قوم نيولے شى. هغه به دا ټول بادشاهتونه مات کړى او ختم به يې کړى، خو دا به د تل دپاره پاتې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20688, 'Daniel 2:45', 'Daniel', 2, 45, '&nbsp;دا د غرۀ نه د کاڼى د راجدا کېدلو د رويا تعبير دے، خو د انسانانو په لاسونو نه، هغه کاڼى چې اوسپنه، زېړ، خاوره، سپين زر او سرۀ زر يې ټوټه کړل. لوئ خُدائ پاک بادشاه ته دا ښودلى دى چې په راتلونکى وخت کښې به څۀ کيږى. دا خوب رښتيا او تعبير يې باورى دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20689, 'Daniel 2:46', 'Daniel', 2, 46, '&nbsp;نو بيا نبوکدنضر بادشاه د دانيال په وړاندې ټيټ شو او د هغۀ عزت يې وکړو او حکم يې وکړو چې هغۀ ته د غلو دانو او د خوشبو نذرانې وړاندې کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20690, 'Daniel 2:47', 'Daniel', 2, 47, '&nbsp;بادشاه دانيال ته ووئيل، ”بې‌شکه ستا خُدائ پاک د ټولو معبودانو خُدائ پاک دے او د بادشاهانو مالِک دے او د رازونو ښکاره کوونکے دے. ځکه چې تا ته دا راز څرګند کړے شو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20691, 'Daniel 2:48', 'Daniel', 2, 48, '&nbsp;بيا بادشاه دانيال ته لوئ مقام ورکړو، او ډيرې او ښکلې تحفې يې ورکړې. بادشاه هغه د بابل په ټوله صوبه باندې حکمران او د ټولو هوښيارانو مشر مقرر کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20692, 'Daniel 2:49', 'Daniel', 2, 49, '&nbsp;نو د دانيال په خواست سره بادشاه شدرک، ميشک، او عبدنجو د بابل د صوبې په انتظاميه کښې آفسران مقرر کړل، او په خپله دانيال په شاهى دربار کښې پاتې شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20693, 'Daniel 3:1', 'Daniel', 3, 1, '&nbsp;نبوکدنضر بادشاه يوه د سرو زرو مجسمه جوړه کړه چې لس کم سل فټه اوچته او نهۀ فټه پلنه وه، او هغۀ هغه د بابل په صوبه کښې د دُورا په مېدان کښې ودروله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20694, 'Daniel 3:2', 'Daniel', 3, 2, '&nbsp;نو بيا بادشاه ټولو حکمرانانو، مشيرانو، خزانچيانو، قاضيانو او د صوبو آفسرانو ته پېغام ولېږلو چې د مجسمې د لګولو مراسمو له راشئ کومه چې هغۀ ودرولې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20695, 'Daniel 3:3', 'Daniel', 3, 3, '&nbsp;نو بيا ټول حکمرانان، مشيران، خزانچيان، قاضيان، او د صوبې نور آفسران د مجسمې د وقف کېدو رسم له راغونډ شول کومه چې نبوکدنضر بادشاه ودرولې وه او د هغې په وړاندې هغوئ ودرېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20696, 'Daniel 3:4', 'Daniel', 3, 4, '&nbsp;نو بيا ډندورچى په اوچت آواز اعلان وکړو، ”اے د ټولو قومونو، ذاتونو او ژبو خلقو، تاسو ته دا حکم دے چې هغه ضرور سر ته ورسوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20697, 'Daniel 3:5', 'Daniel', 3, 5, '&nbsp;څنګه چې تاسو د بيګل، شپيلۍ، رباب، بينجو، سريندې، ستار او هر قسمه موسيقۍ او سازونو آواز واورئ نو هغه د سرو زرو مجسمې ته عبادت او سجده وکړئ کومه چې نبوکدنضر بادشاه ودرولې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20698, 'Daniel 3:6', 'Daniel', 3, 6, '&nbsp;هر هغه څوک چې عبادت او سجده ونۀ کړى نو هغه به سمدستى د اور په لمبه بټۍ کښې وغورزولے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20699, 'Daniel 3:7', 'Daniel', 3, 7, '&nbsp;نو هرکله چې هغوئ د بيګل، شپيلۍ، رباب، بينجو، سريندې، ستار او هر قسمه موسيقۍ او سازونو آواز واورېدو، نو د ټولو خلقو او ټولو قومونو او د هرې ژبې خلقو، هغه د سرو زرو مجسمې ته سجده وکړه او د هغې عبادت يې وکړو، کومه چې نبوکدنضر بادشاه ودرولې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(20700, 'Daniel 3:8', 'Daniel', 3, 8, '&nbsp;نو په دې موقع څۀ نجوميان بادشاه له ورغلل او د يهوديانو خلاف يې سخت شکايت وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');